import React, { useState } from "react";
import axios from "axios";
import { API } from "../config";

function Home() {
  const [vehicle, setVehicle] = useState("");
  const [results, setResults] = useState([]);

  // Search challans by vehicle number
  const searchChallan = async () => {
    if (!vehicle.trim()) return alert("Please enter a vehicle number!");

    try {
      const res = await axios.get(`${API}/challan/vehicle/${vehicle}`);
      setResults(res.data);
      if (res.data.length === 0) alert("No challans found for this vehicle.");
    } catch (err) {
      console.error(err);
      alert("Error fetching challans. Make sure backend is running.");
    }
  };

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h2>Traffic Challan Search</h2>

      <div style={{ marginBottom: 20 }}>
        <input
          type="text"
          placeholder="Enter Vehicle Number"
          value={vehicle}
          onChange={(e) => setVehicle(e.target.value)}
          style={{ padding: 5, marginRight: 10 }}
        />
        <button onClick={searchChallan} style={{ padding: 5 }}>
          Search
        </button>
      </div>

      {results.length > 0 && (
        <div>
          <h3>Challan Results</h3>
          <table border="1" cellPadding="6">
            <thead>
              <tr>
                <th>#</th>
                <th>Vehicle</th>
                <th>Cause</th>
                <th>Fine</th>
                <th>Status</th>
                <th>Issue Date</th>
                <th>Due Date</th>
                <th>Address</th>
              </tr>
            </thead>
            <tbody>
              {results.map((c, i) => (
                <tr key={c._id}>
                  <td>{i + 1}</td>
                  <td>{c.vehicleNumber}</td>
                  <td>{c.cause}</td>
                  <td>{c.fine}</td>
                  <td>{c.status}</td>
                  <td>{c.issueDate}</td>
                  <td>{c.dueDate}</td>
                  <td>{c.address}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {results.length === 0 && vehicle.trim() !== "" && (
        <p>No challans found.</p>
      )}
    </div>
  );
}

export default Home;
